using System;
using System.Collections.Generic;
using System.Linq;

namespace Ascend.Core
{
    // Wave F-lite (upgrade v10 section 9.1): the Great Labyrinth floor registry and the Underworld layer registry.
    // Data/World/labyrinth.json and underworld.json are generated by Tools/atlas/build_labyrinth_registry.js; the
    // rules here only read them. What the player knows is a LabyrinthKnowledge (Unknown / Heard / Visited, the same
    // vocabulary as the map and the dungeon clue record). Hearing never downgrades a visit; a hidden stair opens only
    // when it has been found in place. 12_Systems/world_graph.md.

    // ---- data models --------------------------------------------------------------------------------------------

    public sealed class LabyrinthEntrance
    {
        public string RegionId { get; set; }
        public string Text { get; set; }
        public double[] MapAt { get; set; }
    }

    public sealed class LabyrinthBand
    {
        public string Id { get; set; }
        public string RegionId { get; set; }
        /// <summary>First and last floor of the band (inclusive).</summary>
        public int[] Floors { get; set; } = new int[2];
        public string LicenceRank { get; set; }
        public string Settlement { get; set; }
        public string Name { get; set; }
        public string RankMin { get; set; }
        public string RankMax { get; set; }
        public int Ring { get; set; }
    }

    public sealed class LabyrinthDecade
    {
        public int[] Floors { get; set; } = new int[2];
        public string Biome { get; set; }
        public string RankMin { get; set; }
        public string RankMax { get; set; }
    }

    public sealed class LabyrinthFloor
    {
        public string Id { get; set; }
        public int N { get; set; }
        public string Band { get; set; }
        public string Biome { get; set; }
        public string RankMin { get; set; }
        public string RankMax { get; set; }
        public bool Guardian { get; set; }
        /// <summary>"town" or "camp" on a floor with a safe place; null elsewhere.</summary>
        public string Safe { get; set; }
        public string SafeSource { get; set; }
        public bool Hidden { get; set; }
        public bool Secret { get; set; }
        public List<string> Landmarks { get; set; } = new List<string>();
        public List<string> DungeonIds { get; set; } = new List<string>();
    }

    public sealed class LabyrinthStair
    {
        public string Id { get; set; }
        public int From { get; set; }
        public int To { get; set; }
        public bool Hidden { get; set; }
        public string LicenceRank { get; set; }
    }

    public sealed class LabyrinthBackDoor
    {
        public string Id { get; set; }
        public int Floor { get; set; }
        public int Layer { get; set; }
        public string RegionId { get; set; }
        public bool Hidden { get; set; }
        public string Pairing { get; set; }
    }

    /// <summary>Plain model of Data/World/labyrinth.json.</summary>
    public sealed class LabyrinthData
    {
        public int Version { get; set; }
        public string Id { get; set; }
        public LabyrinthEntrance Entrance { get; set; } = new LabyrinthEntrance();
        public int FloorCount { get; set; }
        public string Resets { get; set; }
        public List<int> StartHeard { get; set; } = new List<int>();
        public List<LabyrinthBand> Bands { get; set; } = new List<LabyrinthBand>();
        public List<LabyrinthDecade> Decades { get; set; } = new List<LabyrinthDecade>();
        public List<LabyrinthFloor> Floors { get; set; } = new List<LabyrinthFloor>();
        public List<LabyrinthStair> Stairs { get; set; } = new List<LabyrinthStair>();
        public List<LabyrinthBackDoor> BackDoors { get; set; } = new List<LabyrinthBackDoor>();
    }

    public sealed class UnderworldGate
    {
        public double[] At { get; set; }
        public string SurfaceRegionId { get; set; }
    }

    public sealed class UnderworldLayer
    {
        public int Layer { get; set; }
        public string RegionId { get; set; }
        public string Name { get; set; }
        public string RankMin { get; set; }
        public string RankMax { get; set; }
        public int Ring { get; set; }
        public UnderworldGate Gate { get; set; } = new UnderworldGate();
        public int RegionsJsonDepth { get; set; }
        /// <summary>Id of the Labyrinth back-door that leads here (null when the layer has none).</summary>
        public string LabyrinthBackDoor { get; set; }
        public bool WeavePressure { get; set; }
    }

    /// <summary>Plain model of Data/World/underworld.json.</summary>
    public sealed class UnderworldData
    {
        public int Version { get; set; }
        public List<UnderworldLayer> Layers { get; set; } = new List<UnderworldLayer>();
    }

    // ---- rules --------------------------------------------------------------------------------------------------

    public enum DescendResult { Ok, BottomFloor, UnknownFloor, NeedsLicence, StairHidden }

    /// <summary>How a floor looks to the player: blank, rumoured, one stair away, or walked.</summary>
    public enum FloorAccess { Unknown, Heard, Reachable, Visited }

    /// <summary>The 120 floors, their bands and stairs. Read-only.</summary>
    public sealed class Labyrinth
    {
        readonly LabyrinthData _d;
        readonly Dictionary<int, LabyrinthStair> _stairFrom = new Dictionary<int, LabyrinthStair>();
        readonly Dictionary<string, LabyrinthStair> _stairById = new Dictionary<string, LabyrinthStair>();
        readonly Dictionary<string, LabyrinthFloor> _floorById = new Dictionary<string, LabyrinthFloor>();

        public LabyrinthData Data => _d;
        public int FloorCount => _d.FloorCount;
        public IReadOnlyList<LabyrinthBand> Bands => _d.Bands;
        public IReadOnlyList<LabyrinthFloor> Floors => _d.Floors;
        public IReadOnlyList<LabyrinthStair> Stairs => _d.Stairs;
        public IReadOnlyList<LabyrinthBackDoor> BackDoors => _d.BackDoors;

        public Labyrinth(LabyrinthData data)
        {
            _d = data ?? throw new ArgumentException("no labyrinth data");
            if (_d.FloorCount < 1) throw new ArgumentException("floor count must be positive");
            if (_d.Floors == null || _d.Floors.Count != _d.FloorCount)
                throw new ArgumentException($"expected {_d.FloorCount} floors, found {_d.Floors?.Count ?? 0}");
            _d.Bands ??= new List<LabyrinthBand>();
            _d.Stairs ??= new List<LabyrinthStair>();
            _d.BackDoors ??= new List<LabyrinthBackDoor>();
            for (int i = 0; i < _d.Floors.Count; i++)
            {
                var f = _d.Floors[i];
                if (f == null || f.N != i + 1) throw new ArgumentException($"floors must be contiguous from 1: position {i + 1} holds {f?.N}");
                if (string.IsNullOrEmpty(f.Id) || !_floorById.TryAdd(f.Id, f)) throw new ArgumentException($"bad or duplicate floor id at {f.N}");
                if (_d.Bands.All(b => b.Id != f.Band)) throw new ArgumentException($"floor {f.N} names an unknown band {f.Band}");
            }
            foreach (var b in _d.Bands)
            {
                if (b.Floors == null || b.Floors.Length != 2 || b.Floors[0] < 1 || b.Floors[1] > _d.FloorCount || b.Floors[0] > b.Floors[1])
                    throw new ArgumentException($"band {b.Id} has bad floors");
                if (!Rank.TryParse(b.LicenceRank, out _)) throw new ArgumentException($"band {b.Id} has a bad licence rank");
            }
            foreach (var s in _d.Stairs)
            {
                if (s == null || s.To != s.From + 1) throw new ArgumentException($"stair {s?.Id} must lead from N to N+1");
                if (s.From < 1 || s.To > _d.FloorCount) throw new ArgumentException($"stair {s.Id} leaves the labyrinth");
                if (s.LicenceRank != null && !Rank.TryParse(s.LicenceRank, out _)) throw new ArgumentException($"stair {s.Id} has a bad licence rank");
                if (string.IsNullOrEmpty(s.Id) || !_stairById.TryAdd(s.Id, s) || !_stairFrom.TryAdd(s.From, s))
                    throw new ArgumentException($"duplicate stair {s.Id}");
            }
            for (int n = 1; n < _d.FloorCount; n++)
                if (!_stairFrom.ContainsKey(n)) throw new ArgumentException($"no stair from floor {n}");
            foreach (var bd in _d.BackDoors)
                if (bd == null || bd.Floor < 1 || bd.Floor > _d.FloorCount) throw new ArgumentException($"back-door {bd?.Id} is on no floor");
        }

        /// <summary>Floor n (1..FloorCount), or null.</summary>
        public LabyrinthFloor Floor(int n) => n >= 1 && n <= _d.FloorCount ? _d.Floors[n - 1] : null;
        public LabyrinthFloor FloorById(string id) => id != null && _floorById.TryGetValue(id, out var f) ? f : null;
        public LabyrinthStair StairById(string id) => id != null && _stairById.TryGetValue(id, out var s) ? s : null;

        public LabyrinthBand BandOf(int n)
        {
            var f = Floor(n);
            return f == null ? null : _d.Bands.FirstOrDefault(b => b.Id == f.Band);
        }

        public LabyrinthBand BandOfRegion(string regionId) => regionId == null ? null : _d.Bands.FirstOrDefault(b => b.RegionId == regionId);

        /// <summary>The stair down from floor n to n+1 (null on the bottom floor or off the map).</summary>
        public LabyrinthStair StairDown(int n) => _stairFrom.TryGetValue(n, out var s) ? s : null;

        public bool IsGuardianFloor(int n) => Floor(n)?.Guardian ?? false;
        public bool IsSafeFloor(int n) => !string.IsNullOrEmpty(Floor(n)?.Safe);
        public LabyrinthBackDoor BackDoorOn(int n) => _d.BackDoors.FirstOrDefault(b => b.Floor == n);
        public IEnumerable<LabyrinthFloor> FloorsWithLandmarks => _d.Floors.Where(f => f.Landmarks != null && f.Landmarks.Count > 0);

        /// <summary>True when the licence (if any) is met by the guild rank letter.</summary>
        public static bool LicenceMet(string licenceRank, RankLetter rank)
            => licenceRank == null || (Rank.TryParse(licenceRank, out var need) && rank >= need.Letter);

        /// <summary>Whether the player can take the stair down from <paramref name="floor"/> (only N to N+1, never skipping).</summary>
        public DescendResult CanDescend(int floor, RankLetter rank, LabyrinthKnowledge know)
        {
            if (Floor(floor) == null) return DescendResult.UnknownFloor;
            var stair = StairDown(floor);
            if (stair == null) return DescendResult.BottomFloor;
            if (!LicenceMet(stair.LicenceRank, rank)) return DescendResult.NeedsLicence;
            if (stair.Hidden && (know == null || know.StatusOfStair(stair.Id) != MapStatus.Visited)) return DescendResult.StairHidden;
            return DescendResult.Ok;
        }

        /// <summary>Takes the stair down; returns the new floor, or the same floor when refused. Arrival is recorded as Visited.</summary>
        public int Descend(int floor, RankLetter rank, LabyrinthKnowledge know)
        {
            if (CanDescend(floor, rank, know) != DescendResult.Ok) return floor;
            know?.VisitFloor(floor + 1);
            return floor + 1;
        }

        /// <summary>Climbing is always allowed, down to floor 1.</summary>
        public int Ascend(int floor) => floor <= 1 ? 1 : Math.Min(floor, _d.FloorCount) - 1;
    }

    /// <summary>What a save keeps of the Labyrinth. Keys are floor ids (flr_007) and stair ids.</summary>
    public sealed class LabyrinthSave
    {
        public Dictionary<string, MapStatus> Floors { get; set; } = new Dictionary<string, MapStatus>();
        public Dictionary<string, MapStatus> Stairs { get; set; } = new Dictionary<string, MapStatus>();
    }

    /// <summary>The player's record of the Labyrinth: Unknown / Heard / Visited per floor and per stair.</summary>
    public sealed class LabyrinthKnowledge
    {
        readonly Labyrinth _lab;
        readonly Dictionary<int, MapStatus> _floors = new Dictionary<int, MapStatus>();
        readonly Dictionary<string, MapStatus> _stairs = new Dictionary<string, MapStatus>();

        /// <summary>Highest Visited floor, 0 if none.</summary>
        public int Deepest { get; private set; }

        public LabyrinthKnowledge(Labyrinth lab)
        {
            _lab = lab ?? throw new ArgumentNullException(nameof(lab));
            foreach (var n in _lab.Data.StartHeard ?? new List<int>()) HearFloor(n);
        }

        public MapStatus StatusOfFloor(int n) => _floors.TryGetValue(n, out var s) ? s : MapStatus.Unknown;
        public MapStatus StatusOfFloor(string floorId) => StatusOfFloor(_lab.FloorById(floorId)?.N ?? 0);
        public MapStatus StatusOfStair(string stairId) => stairId != null && _stairs.TryGetValue(stairId, out var s) ? s : MapStatus.Unknown;

        /// <summary>A rumour pencils a floor in; true if it was blank before.</summary>
        public bool HearFloor(int n)
        {
            if (_lab.Floor(n) == null || StatusOfFloor(n) != MapStatus.Unknown) return false;
            _floors[n] = MapStatus.Heard;
            return true;
        }

        /// <summary>Inks a floor (arrived in place); true if it was not inked before.</summary>
        public bool VisitFloor(int n)
        {
            if (_lab.Floor(n) == null || StatusOfFloor(n) == MapStatus.Visited) return false;
            _floors[n] = MapStatus.Visited;
            if (n > Deepest) Deepest = n;
            return true;
        }

        /// <summary>A rumour of a stair: pencils it but opens nothing.</summary>
        public bool HearStair(string stairId)
        {
            if (_lab.StairById(stairId) == null || StatusOfStair(stairId) != MapStatus.Unknown) return false;
            _stairs[stairId] = MapStatus.Heard;
            return true;
        }

        /// <summary>Finds a stair in place; this is what opens a hidden one. True if it was not found before.</summary>
        public bool FindStair(string stairId)
        {
            if (_lab.StairById(stairId) == null || StatusOfStair(stairId) == MapStatus.Visited) return false;
            _stairs[stairId] = MapStatus.Visited;
            return true;
        }

        /// <summary>Pencils or inks each band's land on the map to match the floors known. Returns how many regions changed.</summary>
        public int SyncToMap(MapKnowledge map)
        {
            if (map == null) return 0;
            int changed = 0;
            foreach (var b in _lab.Bands)
            {
                bool visited = false, heard = false;
                for (int n = b.Floors[0]; n <= b.Floors[1]; n++)
                {
                    var s = StatusOfFloor(n);
                    if (s == MapStatus.Visited) { visited = true; break; }
                    if (s == MapStatus.Heard) heard = true;
                }
                if (visited) { if (map.Visit(b.RegionId)) changed++; }
                else if (heard) { if (map.Hear(b.RegionId)) changed++; }
            }
            return changed;
        }

        /// <summary>Known / discovered / reachable / inaccessible, for the map and floor list.</summary>
        public FloorAccess AccessOf(int n, RankLetter rank)
        {
            if (_lab.Floor(n) == null) return FloorAccess.Unknown;
            if (StatusOfFloor(n) == MapStatus.Visited) return FloorAccess.Visited;
            if (n == 1) return FloorAccess.Reachable; // the entrance is always open
            if (StatusOfFloor(n - 1) == MapStatus.Visited && _lab.CanDescend(n - 1, rank, this) == DescendResult.Ok) return FloorAccess.Reachable;
            return StatusOfFloor(n) == MapStatus.Heard ? FloorAccess.Heard : FloorAccess.Unknown;
        }

        public LabyrinthSave Save()
        {
            var s = new LabyrinthSave();
            foreach (var kv in _floors) s.Floors[_lab.Floor(kv.Key).Id] = kv.Value;
            foreach (var kv in _stairs) s.Stairs[kv.Key] = kv.Value;
            return s;
        }

        /// <summary>Restores a save. Null changes nothing; unknown ids are ignored; nothing is downgraded.</summary>
        public void Load(LabyrinthSave save)
        {
            if (save == null) return;
            foreach (var kv in save.Floors ?? new Dictionary<string, MapStatus>())
            {
                var f = _lab.FloorById(kv.Key);
                if (f == null) continue;
                if (kv.Value == MapStatus.Visited) VisitFloor(f.N);
                else if (kv.Value == MapStatus.Heard) HearFloor(f.N);
            }
            foreach (var kv in save.Stairs ?? new Dictionary<string, MapStatus>())
            {
                if (kv.Value == MapStatus.Visited) FindStair(kv.Key);
                else if (kv.Value == MapStatus.Heard) HearStair(kv.Key);
            }
            Deepest = _floors.Where(kv => kv.Value == MapStatus.Visited).Select(kv => kv.Key).DefaultIfEmpty(0).Max();
        }
    }

    /// <summary>The five Underworld layers. Discovery is plain MapKnowledge on the layer's region id.</summary>
    public sealed class UnderworldRegistry
    {
        readonly List<UnderworldLayer> _layers;
        readonly Labyrinth _lab;

        public UnderworldRegistry(UnderworldData data, Labyrinth labyrinth)
        {
            if (data?.Layers == null || data.Layers.Count == 0) throw new ArgumentException("no underworld layers");
            _lab = labyrinth ?? throw new ArgumentException("the underworld needs the labyrinth");
            _layers = data.Layers.ToList();
            for (int i = 0; i < _layers.Count; i++)
            {
                var l = _layers[i];
                if (l == null || l.Layer != i + 1) throw new ArgumentException($"layers must run 1..N in order: position {i + 1} holds {l?.Layer}");
                if (string.IsNullOrEmpty(l.RegionId) || _layers.Take(i).Any(o => o.RegionId == l.RegionId)) throw new ArgumentException($"layer {l.Layer} has a bad or duplicate region");
                if (!Rank.TryParse(l.RankMin, out _)) throw new ArgumentException($"layer {l.Layer} has a bad rank");
                if (l.LabyrinthBackDoor != null)
                {
                    var bd = _lab.BackDoors.FirstOrDefault(b => b.Id == l.LabyrinthBackDoor);
                    if (bd == null || bd.Layer != l.Layer || bd.RegionId != l.RegionId)
                        throw new ArgumentException($"layer {l.Layer} names a back-door that does not lead to it");
                }
            }
        }

        public IReadOnlyList<UnderworldLayer> Layers => _layers;
        public UnderworldLayer Layer(int n) => n >= 1 && n <= _layers.Count ? _layers[n - 1] : null;
        /// <summary>The next layer down, or null after the last.</summary>
        public UnderworldLayer Next(int n) => n >= 1 ? Layer(n + 1) : null;
        public UnderworldLayer ByRegion(string regionId) => regionId == null ? null : _layers.FirstOrDefault(l => l.RegionId == regionId);

        /// <summary>The layer's RankMin is its licence.</summary>
        public bool CanEnter(int layer, RankLetter rank)
        {
            var l = Layer(layer);
            return l != null && Rank.TryParse(l.RankMin, out var need) && rank >= need.Letter;
        }

        /// <summary>The Labyrinth floor whose back-door leads to this layer, or 0.</summary>
        public int BackDoorFloor(int layer) => _lab.BackDoors.FirstOrDefault(b => b.Layer == layer)?.Floor ?? 0;
        /// <summary>The layer a Labyrinth floor's back-door leads to, or 0.</summary>
        public int LayerOfBackDoor(int floor) => _lab.BackDoorOn(floor)?.Layer ?? 0;
        public bool HasWeavePressure(int layer) => Layer(layer)?.WeavePressure ?? false;
    }
}
